"use strict";

globalThis.QuimiCraftCatalogLore=(()=>{
  const notes={
    curupira:["Os guias da mata repetem histórias indígenas sobre um guardião de cabelo aceso. Quem seguiu suas pegadas voltou ao mesmo toco três vezes. Na última, encontrou a própria faca cravada na casca.","As árvores das copas ainda se lembram do assobio.",["living_tree_warden","O assobio na copa"],["jaguar","O rastro que ficou inteiro"]],
    saci:["O carvoeiro jurava que o caminho tinha voltado a si mesmo por causa do vento. Só as cinzas ouviram o menino rir. Pela manhã, o gorro vermelho aparecia no desenho e nenhuma pegada acompanhava a outra.","A fumaça do cachimbo sobe até quando o vento sopra para baixo.",["boitata","Outra fogueira apagada"],["block:TORCH","A chama que se inclinou"]],
    boitata:["Antes dos lampiões, as histórias indígenas já falavam de um fogo comprido que vigiava campos e banhados. O avistamento mais antigo termina numa curva de ouro sobre a água e numa linha intacta de capim.","As marcas no chão acabam onde a chama faz a primeira curva.",["headless_mule","Onde o fogo deixou cascos"],["block:ASH","A faixa intacta"]],
    pink_boto:["Nas noites de festa do rio, os remadores contam um convidado a mais. Ele usa roupa branca, guarda o chapéu mesmo na dança e some antes do primeiro café. Pouco depois, um dorso rosa corta o remanso.","Entre dois salpicos, a água fica lisa como a aba de um chapéu.",["boat","A travessia do remanso"],["fishfolk_head","Quem ainda deixou pegadas"]],
    headless_mule:["O relato da velha estrada fala de uma promessa quebrada e de cascos correndo da quinta para a sexta. O vulto escuro sobe a ladeira com o pescoço em chamas. A patrulha reconhece a curva pelo cheiro de crina queimada.","O fogo corre atrás dela quando acelera.",["boitata","O outro clarão da noite"],["block:VILLAGE_BRICK","Sob a soleira chamuscada"]],
    werewolf:["A primeira lua cheia encontrou a porta do curral aberta por dentro. Havia retalhos marrons nos pregos e sulcos fundos nas tábuas. Na manhã seguinte alguém devolveu a roupa, dobrada, com o nome raspado.","O único sulco interrompido atravessava uma lâmina de prata.",["block:SILVER_ORE","O sulco interrompido"],["wolf","A distância entre as marcas"]],
    npc_carbon:["O livro de entrada do Laboratório Carbono conserva uma folha sem número. Carbono registra ali os resultados que se repetem em lugares distantes. Há um desenho de cristais no papel, exatamente por cima da marca de uma maré.","A folha foi guardada seca. O mapa que a acompanhava ainda cheirava a sal.",["block:SUNKEN_MOSAIC","O desenho sob a água"],["block:LAB","A folha sem número"]],
    npc_ranger:["Íris traça rotas usando pegadas, altura da maré e o lugar onde o vento mudou. Só uma trilha em seu mapa termina no meio de uma clareira. A seta nessa página tem duas pontas.","A marca de três cortes reaparece em fichas da mata.",["curupira","A seta de duas pontas"],["deer","Onde os cortes reaparecem"]],
    ruin_medusa:["Estátuas velhas nas ruínas têm o rosto voltado para o pátio. As mais novas levam a mão aos olhos. Entre elas, a Medusa recolhe pedaços de vidro em que ainda cabem as colunas inteiras.","A única figura que saiu do pátio carregava a luz voltada para trás.",["shield_mirror","A luz voltada para trás"],["salt_medusa","O mesmo gesto no sal"]],
    salt_medusa:["A crosta de sal conserva cada volta das serpentes quando elas passam ao amanhecer. As figuras da salina olham para a borda das poças, onde a água devolve o céu por poucos instantes.","Uma figura isolada carrega sal apenas no rosto.",["ruin_medusa","A posição das estátuas"],["block:SALT","O rosto guardado no sal"]],
    obsidian_medusa:["Na caldeira, as estátuas afastadas das brasas ainda têm bordas afiadas. A Medusa passa rente às rochas escuras. O rosto dela só ficou nítido no metal polido da equipe que voltou.","O chão conserva dois reflexos para uma única sombra.",["shield_mirror","O viajante que olhou de volta"],["block:BASALT_GLASS","O segundo reflexo"]],
    shield_mirror:["O ferreiro começou pelo desenho de uma estátua com um braço levantado. O que ele trouxe das ruínas cabia na palma da mão. Levou meia estação para polir metal suficiente e devolver o pátio inteiro ao seu reflexo.","Há marcas de dentes na borda e de sal no verso.",["ruin_medusa","O braço levantado"],["salt_medusa","Os grãos no verso"]],
    buffer_armor:["O primeiro protótipo voltou do brejo com as placas foscas e um reservatório quase vazio. A responsável pelo ensaio anotou o volume que restava antes de registrar o estado das placas. A segunda armadura conserva a mesma ordem de inspeção.","A névoa que deixou as placas foscas tinha o mesmo tom da Geleia de Turfa.",["slime","A marca corrosiva"],["peat_slime","O ensaio do brejo"]],
    ear_protectors:["No registro dos hortelãos, o primeiro par foi costurado com lã seca ao lado de uma janela fechada. O som do lado de fora atravessava as vidraças. Atrás delas, todas as pétalas pareciam imóveis.","O registro seguinte só menciona o barulho da própria tesoura.",["screamer:forest","A janela fechada"]],
    ice_dragon:["Já encontraram a silhueta do Dragão Azul sob a primeira camada de gelo de um lago. De cima, a cabeça e a cauda formavam dois limites diferentes do degelo. Ninguém marcou o centro no mapa.","Pequenas fraturas apontavam para o lado oposto ao vento.",["block:BLUE_ICE_VEIN","A fratura submersa"],["aurora_phantom","O que veio depois do degelo"]],
    fire_dragon:["A pedra mais escura do covil conserva um brilho laranja no fundo das rachaduras. A patrulha passou o inverno olhando de longe. Na primeira manhã em que as aves voltaram, as rachaduras ainda estavam quentes.","O desenho das asas começa atrás da última marca de calor.",["block:MAGMA_ROCK","A última marca quente"],["den_sentinel","A vigília no covil"]],
    nature_dragon:["Nas clareiras em que o Dragão Verde pousa, frutos e pólen ficam presos entre as escamas. Os guias mais velhos desenham esses lugares a partir das árvores que dão sombra umas às outras.","Sobre um ninho vazio cresceu um ramo que não aparecia no mapa anterior.",["living_tree_elder","A árvore fora do mapa"],["jabuticaba","Um fruto junto às escamas"]],
    time_dragon:["Duas patrulhas registraram o mesmo voo do Dragão Bronze. No caderno antigo, a sombra vai da praça para a serra. No caderno novo, ela passa por cima das pegadas que a primeira patrulha ainda faria.","As duas fivelas de bronze foram achadas no mesmo batente.",["block:BRONZE_BLOCK","As marcas no batente"],["npc_carbon","As folhas fora de ordem"]],
    earth_dragon:["Antes de se ver o Dragão de Terra, o chão responde em três batidas. A primeira mexe no pó, a segunda move pedras pequenas. No registro da mina, o intervalo depois da terceira ficou em branco.","A pedra que abafou o sino nunca se moveu da encosta.",["block:DEEPSTONE","O intervalo na pedra"],["iron_armadillo","Três montes de terra"]],
    cow:["As manchas das vacas do vale permitem aos pastores identificar os rebanhos de longe. A mesma cabeça escura reaparece nos desenhos de duas margens. Entre as duas páginas, a marca de ferro do portão mudou de lado.","Os bezerros repetem o caminho que passa pela sombra.",["cow:baby","O mesmo caminho"],["block:GATE_WOOD","A marca no curral"]],
    pig:["Os porcos reviram as bordas da horta ao cair da tarde. Na estação chuvosa, a linha das pegadas cresce na direção das raízes que a água deixa à vista.","Os sulcos mais recentes terminam sempre diante de outra planta.",["beet","O que ficou sob o barro"]],
    rabbit:["O coelho comum alterna disparadas pelos campos com longos períodos encostado à entrada da toca. Tocas vizinhas costumam ter saídas voltadas para lados opostos.","É mais fácil contar as saídas depois que a grama cresce.",["snow_hare","A saída na neve"]],
    chicken:["As galinhas da vila se abrigam na mesma beirada sempre que o vento vira. Todo ano a primeira pena debaixo dela anuncia uma mudança na estação.","Há penas no lado protegido até depois de um temporal.",["block:FENCE_BAMBOO","O lado protegido"]],
    sheep:["Ao subir os prados, as ovelhas baixam o focinho nos bolsões onde a grama continua verde. A lã presa nas cercas aponta para o caminho que o rebanho usou na véspera.","Um fio claro ficou preso ao cravo na armação da cama.",["block:BED","O fio no cravo"]],
    deer:["Patrulheiros da taiga reconhecem os cervos pelo intervalo entre os saltos. Em caminhos usados por várias estações, as galhadas deixam cortes em alturas que nunca se repetem.","Em uma única árvore todos os cortes estavam virados para dentro.",["npc_ranger","O mapa de Íris"],["forest_deer","A trilha mais baixa"]],
    owl:["A coruja sai quando as trilhas claras deixam de refletir o céu. O primeiro esboço de suas asas foi feito seguindo as penas encontradas do ninho até o lugar de caça.","O silêncio da asa termina quando outra coisa responde do chão.",["screamer:cold","A resposta do solo"]],
    capivara:["As capivaras se juntam nas margens onde o barranco desce sem degraus. Os grupos mais antigos repetem o mesmo retorno à água e deixam uma rampa marcada no barro.","A rampa permanece mesmo quando a corrente muda.",["caiman","Junto à rampa"]],
    cat:["Perto das casas, os gatos seguem a linha quente que o sol deixa no telhado. Seus bigodes costumam tocar a beirada antes de qualquer parte do corpo.","Em uma oficina, duas pequenas pegadas atravessam a poeira de uma janela sob o beiral.",["block:GLASS","A janela do beiral"],["lynx","O parente de orelhas altas"]],
    dog:["Nas vilas, alguns cães seguem o cheiro de quem voltou por uma estrada diferente. Os ferreiros reconhecem a chegada pela forma como as orelhas se inclinam na direção do portão.","Nas encostas, a mesma escuta pertence a outro focinho.",["wolf","O focinho da encosta"]],
    jaguar:["As rosetas largas escondem a onça quando ela anda sob folhas entreabertas. Em margens alagadas, as pegadas largas entram na água sem perder o alinhamento.","Onde a água apaga o rastro, um guardião ainda se volta para a margem.",["curupira","O guardião da margem"],["tiger","Listras no mesmo tipo de sombra"]],
    tiger:["A faixa escura da cara do tigre muda de direção perto dos olhos. Um guia das sequoias desenhou só essa parte. O resto do corpo já tinha sumido entre as listras de sombra.","As pegadas das patas traseiras chegam quase dentro das primeiras.",["jaguar","Uma pegada de outra margem"]],
    lion:["A juba guarda pó depois da chuva, mesmo quando o resto do leão já está seco. Na savana, os viajantes ouvem o primeiro chamado nas áreas onde o relevo devolve o som.","O eco marca o limite da parte aberta da chapada.",["block:OCHRE_STONE","A parede que devolve o chamado"]],
    wolf:["O lobo cheira de lado ao passar pelos troncos da taiga. O rastro de um viajante só fica mais fundo de um lado quando ele se detém. O seu, quando se detém, vira todo na mesma direção.","O intervalo cresce nas noites em que se ouve uma segunda voz.",["werewolf","A segunda voz"],["rime_fox","O rastro menor da geada"]],
    lynx:["Encontra o caminho entre agulhas secas e manchas de neve, com tufos escuros acima das orelhas. Quando salta do mesmo ponto duas vezes, as patas anteriores pousam em marcas quase iguais.","Na neve, a cauda curta deixa espaço entre o corpo e a trilha.",["rime_fox","A outra trilha curta"]],
    fennec:["As pegadas do feneco são rasas junto à entrada da toca. Em noites frias, as orelhas captam movimento nas placas finas de areia antes que elas se quebrem.","Há um desenho de duas orelhas na margem de um mapa de salinas.",["salt_crab","Do outro lado da placa"]],
    rime_fox:["A raposa das geadas caminha rente às saliências que cortam o vento. O pincel grosso da cauda deixa um traço curto quando ela descansa na neve.","A neve do traço costuma derreter primeiro.",["ice_dragon","O gelo que demora"],["wolf","A marca mais funda"]],
    opossum:["O saruê atravessa de noite as margens mais baixas. Usa a cauda para se firmar enquanto as patas procuram a próxima raiz. Atrás dele sobra o fruto caído que deu início à travessia.","Às vezes o fruto volta a aparecer numa raiz mais alta.",["jabuticaba","O fruto sob a raiz"]],
    anteater:["O tamanduá vira a cabeça para baixo ao aproximar-se dos montes de terra. Nas chapadas, a faixa no dorso parece continuar pela sombra de um galho alto.","O cascalho dos montes escavados aponta para as partes secas do campo.",["iron_armadillo","O cascalho que se move"]],
    brown_bear:["Os ursos-pardos voltam aos mesmos troncos caídos quando começa a época dos frutos. A altura das unhas na casca distingue quem passou em cada estação.","Troncos mais antigos têm marcas de um urso de outra cor.",["black_bear","As unhas na casca"]],
    black_bear:["Nas sequoias, o urso-negro anda sob o ponto mais baixo da copa. Parte do pelo fica presa na casca e pode ser encontrada quando a sombra muda.","A parte de cima do mesmo tronco guarda outras marcas.",["block:REDWOOD_LOG","O pelo preso na casca"]],
    polar_bear:["O focinho estreito do urso-polar fica baixo ao cruzar as bordas do gelo. Quando a água leva a passagem, ele espera numa pequena elevação de onde ainda se vê o lado de lá.","Algumas trilhas terminam com o desenho de um grupo de dorsais.",["orca","Os dorsos no canal"]],
    bison:["A pradaria guarda corredores estreitos onde os bisões passam. A altura das plantas mostra por quanto tempo o grupo deixou o lugar em paz.","As trilhas antigas ainda aparecem em épocas de recuperação do pasto.",["block:GRASS","O corredor de grama"]],
    badger:["O texugo puxa cascalho debaixo de pedras calcárias e comprime a borda da entrada com o corpo. Um mapa antigo confundiu esses pequenos amontoados com marcas de minério.","Quando dois vizinhos escavam, a passagem se divide em três.",["block:LIMESTONE","Sob a pedra clara"]],
    iron_armadillo:["O casco do tatu de hematita muda de tom na luz e suas placas fecham-se quando o solo vibra. As primeiras pás que atravessaram essas tocas deixaram marcas voltadas para dentro.","As pilhas de cascalho aparecem antes de se ouvir a escavação.",["block:IRON","A faixa de hematita"],["earth_dragon","As batidas que chegaram depois"]],
    slime:["O gel das poças profundas avança em saltos e deixa cobre e couro opacos onde encosta. A equipe do laboratório só distinguiu a borda do primeiro exemplar observando a película que ele deixou na pedra.","A segunda marca estava num reservatório ainda pela metade.",["buffer_armor","O reservatório pela metade"],["peat_slime","A marca da outra poça"]],
    peat_slime:["O corpo da Geleia de Turfa guarda o tom do sedimento onde cresceu. No fim das chuvas, surgem pequenas manchas verdes sobre a faixa mais escura da margem.","O rastro seco mudou a aparência de uma placa recém-lavada.",["slime","O mesmo ataque em outra cor"],["buffer_armor","A placa fosca"]],
    cobrete:["O cobre exposto nas juntas envelhece em ritmos diferentes. Na primeira manhã após uma frente fria, os ferreiros encontraram as partes móveis quentes e a placa do peito coberta de umidade.","Há uma marca de oficina na engrenagem virada para dentro.",["block:COPPER","A cor da primeira junta"],["npc_carbon","A marca de oficina"]],
    cristalume:["Sua carapaça passa luz pelas arestas quando bate as asas. Observadores marcam os locais onde o brilho muda de cor ao longe. Esses pontos nunca coincidem com os pontos de pouso.","Perto dos geodos, os dois brilhos parecem vir de uma única rachadura.",["block:CRYSTAL","A rachadura luminosa"]],
    golem:["Pedaços de obsidiana voltam a ocupar o mesmo lugar depois que o Golem deixa de andar. Um mineiro descreveu a primeira estátua no caminho como se fosse uma coisa que ainda procurava onde pousar a mão.","Pó escuro permanece nas juntas de todas as cópias.",["block:OBSIDIAN","O pó escuro"],["obsidian_medusa","A estátua que não se recompõe"]],
    magma:["As partes frias do Elemental racham quando o núcleo volta a pulsar. A borda avança para onde a encosta ainda guarda calor, deixando pedras mais escuras do lado contrário.","As fissuras do solo repetem o contorno só enquanto a encosta permanece quente.",["block:MAGMA_ROCK","Uma fissura ainda quente"]],
    scorpion:["O escorpião desenha uma meia-lua com a ponta da cauda ao voltar para a areia. Quando a duna cede, a marca fica ligeiramente maior que seu esconderijo.","O mesmo arco já apareceu perto de uma pegada muito mais leve.",["fennec","Uma pegada leve na mesma duna"]],
    wisp:["O Espectro aparece antes de a tempestade tocar o chão. Seu núcleo se inclina, os aros se desencontram, e pouco depois a água começa a escorrer na direção escolhida.","Uma testemunha marcou o clarão antes do trovão com duas linhas separadas.",["aurora_phantom","O segundo desenho"]],
    orca:["As orcas do mar frio passam pelos canais em grupo. As manchas junto aos olhos ajudam a reconhecer quem voltou em cada estação. Um grupo passa a mesma ponta de gelo sem deixar um único dorso sozinho.","Às vezes o canal fica silencioso minutos antes de outra baleia subir.",["humpback","O canto depois do silêncio"],["polar_bear","O ponto do alto"]],
    humpback:["A jubarte leva cicatrizes no dorso e tubérculos em volta do focinho. Vigiando a maré nas bacias profundas, os remadores reconhecem uma nadadeira comprida antes de o resto da baleia tocar o ar.","Ao amanhecer, o último trecho de seu canto coincide com o som que sobe de certas ruínas.",["block:SUNKEN_BEACON","O som que sobe"],["orca","Quem atravessa o mesmo canal"]],
    dolphin:["Golfinhos de mar aberto acompanham a proa por alguns instantes. Quando a espuma some, eles voltam por um arco mais largo. No encontro entre água salgada e doce, existe um peixe que faz o arco para o outro lado.","O guia dos barcos separa as duas formas pelo dorso.",["pink_boto","O arco em água doce"]],
    mermaid:["Os remadores da costa reconhecem primeiro o movimento das mãos. Em manhãs calmas, uma sereia pode nadar junto à sombra do casco antes de sumir em direção à bacia mais funda.","O canto breve foi anotado ao lado de duas silhuetas parecidas.",["fishfolk_tail","Uma silhueta do cais"],["humpback","O canto mais profundo"]],
    fishfolk_tail:["O homem-peixe de cauda acompanha a borda de água salgada perto dos estuários. Em águas turvas suas mãos somem primeiro. As marcas da cauda no fundo permitem reencontrar sua direção.","Entre duas marcas de cauda apareceram pegadas inteiras.",["fishfolk_head","As pegadas no fundo"],["mermaid","O canto de outra margem"]],
    fishfolk_head:["Do cais parecem pés humanos, um por vez, saindo da lama. A cabeça de peixe só aparece quando o morador do fundo chega ao limite da água. As escamas perto do ombro trazem grãos da mesma margem.","A cauda que faltava foi desenhada numa página vizinha.",["fishfolk_tail","A cauda na página vizinha"],["pink_boto","O visitante sem pegadas"]],
    caiman:["O jacaré deixa só olhos e narinas sobre a água rasa. Em dias sem vento, o pequeno V diante do focinho continua reto até a rampa do barranco.","Os animais da margem mudam de rampa antes de o V aparecer.",["capivara","A rampa abandonada"]],
    piranha:["Quando a água tropical recua, as piranhas ocupam as faixas fundas que ficam entre raízes. O cardume muda junto de direção, deixando um único clarão prateado.","De cima, o brilho parece subir do fundo em vez de seguir a corrente.",["raw_pacu","Um vizinho de perfil parecido"]],
    reef_shark:["O cação desenha voltas abertas acima das pedras do mar. A sombra larga corta a água antes de a dorsal cruzar a superfície.","Em águas rasas, a mesma área guarda uma criatura que quase não levanta o fundo.",["ray","O fundo quase imóvel"]],
    ray:["A raia acompanha o contorno do leito marinho. Sobra um intervalo curto entre suas passagens, quando os grãos do fundo voltam a assentar.","A raia de águas salobras deixa uma linha mais longa onde a cauda tocou.",["venom_ray","A linha no sedimento"]],
    venom_ray:["As bordas da arraia venenosa se confundem com sedimento remexido. Quando expõe a cauda, o rastro no lodo segue reto até um trecho de água mais fria.","As marcas curvas pertencem à vizinha de fundo.",["ray","As marcas curvas"]],
    pufferfish:["Perto do costão, o baiacu mantém o corpo estreito até que a sombra de algo maior passe por baixo dele. A seguir, surgem silhuetas redondas em uma fileira frouxa.","O barco mais baixo do cais permite ver a mudança de perto.",["dinghy","A sombra do bote"]],
    jelly:["A água-viva flutua até onde a corrente enfraquece. No alto mar, seu brilho aparece e some sobre a mesma faixa de água, junto de partículas que seguem adiante.","O movimento fica mais lento antes do canal frio.",["orca","O canal mais frio"]],
    cart:["Foi montado a partir de um desenho encontrado no verso de uma rota de amostras. O chassi ainda tem um encaixe que coincide com as caixas do laboratório. O desenho original terminava justamente antes do trecho inundado.","Nas rodas ficaram duas terras de cores diferentes.",["drill","O restante do trajeto"],["boat","O trecho que ficou debaixo d'água"]],
    drill:["A broca abriu o primeiro atalho até uma nascente esquecida. As marcas helicoidais pararam pouco antes do teto. No diário, essa última parede tem um ponto marcado com tinta azul.","A máquina seguinte foi projetada para recolher o material deixado ali.",["bucket","O material do atalho"],["block:DEEPSTONE","A parede antes da nascente"]],
    bucket:["A caçamba foi desenhada para separar cascalho e peças de antigos cortes. O primeiro lote extraído continha tijolos de dois povoados e uma dobradiça grossa. A dobradiça não aparece nos registros dos povoados.","A fita de aferição da caçamba coincide com a largura de um portão.",["drill","O mesmo corte"],["block:GATE_IRON","A largura da dobradiça"]],
    glider:["O primeiro diagrama do 14-bis de Campo marca uma subida com a ponta oposta à bússola. As notas repetem a direção tomada pelos pássaros na encosta, embora o vento das duas páginas venha de lados diferentes.","A borda de uma das pranchas tem uma correia desenhada a lápis.",["glider_motor","A correia desenhada"],["owl","O voo usado como medida"]],
    glider_motor:["O módulo a pedal foi montado depois que o mesmo 14-bis chegou duas vezes a uma encosta sem vento. As duas polias têm marcas de oficinas diferentes. Uma delas cabe no desenho antigo do primeiro avião.","A segunda foi traçada junto às medidas de um barco.",["glider","A primeira polia"],["speedboat","O desenho que viajou"]],
    dinghy:["O fundo raso do bote permitia atravessar antes da enchente. Na primeira temporada ele voltou cheio de junco cortado. Quando o rio subiu, o mesmo junco já crescia do lado de dentro do último degrau do cais.","Um entalhe antigo mede a água na caixa de bordo.",["boat","Outro entalhe na mesma altura"],["block:REED","O junco do primeiro lote"]],
    boat:["O barco médio guardava a carga abaixo da linha dos bancos nas travessias do remanso. Uma viagem teve seis passageiros na ida e o mesmo número na volta. Só faltou o chapéu no registro de carga.","A maré entrou no desenho junto da última rasura.",["pink_boto","O chapéu que faltou"],["ship","A mesma rasura no cais"]],
    ship:["O barco grande foi montado para cruzar bacias em que a água escurece antes do fundo aparecer. Pelo lado interno do baú, o mestre de obras riscou uma figura geométrica repetida na margem de seu mapa.","Seu último itinerário desapareceu na mesma altura da linha azul.",["block:SUNKEN_MOSAIC","O desenho repetido"],["humpback","O canto perto da linha azul"]],
    speedboat:["A lancha passou a fazer o caminho externo do costão quando os barcos de carga começaram a se atrasar. Pela forma da espuma, a oficina identificava a volta antes de ver a proa.","A última volta do dia costuma cruzar outra espuma na mesma direção.",["dolphin","A espuma que acompanha"],["glider_motor","O desenho do mecanismo"]],
    "screamer:forest":["O botão da mata guarda o som do chão enquanto as pétalas parecem secas. O primeiro grito registrado veio depois que uma pedra rolou para dentro do canteiro.","A testemunha saiu com folhas na bota e lã presa no ouvido.",["ear_protectors","A lã no ouvido"],["curupira","Outro som na mata"]],
    "screamer:marsh":["No brejo, as raízes se espalham pelas margens de lama mole. Uma sequência de gotas pode fazer o botão tremer. O som mais forte foi ouvido quando o nível da água baixou depressa.","Restaram círculos no lodo, longe das raízes.",["peat_slime","Os círculos do brejo"]],
    "screamer:dry":["Nas chapadas, as pétalas guardam a cor do arenito ao fechar. Pedras soltas fazem o botão virar antes do grito. As passagens estreitas devolvem o som em intervalos.","Uma trilha saiu do cânion antes do segundo eco.",["block:OCHRE_STONE","A rocha do segundo eco"],["fennec","A trilha que saiu"]],
    "screamer:cold":["O Gritador da Serra fica rente ao chão sob o gelo fino. Desperta quando um pé quebra a crosta. Do alto, a marca de pétalas abertas aparece antes da primeira rachadura.","Penas da coruja ficam imóveis durante a abertura.",["owl","O silêncio na asa"],["ear_protectors","O som atrás da lã"]],
  };
Object.assign(notes,{
    "block:FARMLAND":["As primeiras marcas de enxada atravessavam a horta do lado que recebia mais água. O canteiro voltou a produzir quando os hortelãos abriram um intervalo entre as últimas fileiras.","Na mesa da horta ainda há um desenho dessa abertura.",["block:SEED_BENCH","O desenho do canteiro"]],
    "block:BLUE_ICE_VEIN":["O veio azul aparece na parte que mais demora a descongelar. Uma fenda alta demais para alcançar pela margem cruza a superfície a partir de baixo.","O mapa do Dragão Azul conserva o mesmo corte virado para o lago.",["ice_dragon","A fenda no mapa do lago"],["raw_char","O brilho sob a fenda"]],
    "block:GLACIAL_GRAVEL":["O cascalho traz seixos de tamanhos diferentes, reunidos no ponto onde o gelo deixou de avançar. Na primeira coleta, as peças maiores ainda guardavam o pó do lado que ficou coberto.","A trilha mais rasa indica um caminho de volta ao gelo.",["rime_fox","A trilha no degelo"],["block:BLUE_ICE_VEIN","A próxima camada"]],
    "block:MARBLE":["A face cortada guarda linhas mais claras que o corpo da pedra. Alguns lotes foram reunidos pela direção dos veios para formar o piso de uma antiga oficina.","Na bancada ao lado, as linhas seguem sob o primeiro frasco.",["block:LAB","Debaixo do primeiro frasco"]],
    "block:SLATE":["A ardósia se separa em lâminas que guardam o relevo de uma face na próxima. Depois da chuva, os viajantes liam a diferença de tom para saber onde o caminho secava primeiro.","Há telhas no vale com o mesmo tipo de borda.",["block:ROOF_BLUE","A borda mais alta"]],
    "block:LIMESTONE":["As margens do cânion foram desenhadas a partir das cavidades na pedra clara. Uma dessas cavidades se repete em camadas, como se o fundo já tivesse sido superfície.","Ao pé da parede, o cascalho forma pequenos montes.",["badger","Os montes do cânion"],["block:TRAVERTINE","A pedra que a água deixou"]],
    "block:TRAVERTINE":["Cada faixa de travertino se assentou onde a água deixou parte do que carregava. Perto das termas, as bandas mudam de espessura na altura em que a água volta a escorrer.","A faixa cor de mel aparece num caderno de amostras.",["block:BANDED_CALCITE","O veio cor de mel"]],
    "block:OCHRE_STONE":["Ao anoitecer, a face do arenito ocre mantém uma cor que as pedras ao redor já perderam. Foi assim que os guias separaram a parede antiga do corte que leva às chapadas.","A última faixa recebe um eco mesmo com o caminho vazio.",["lion","De onde volta o eco"],["screamer:dry","Outra resposta da parede"]],
    "block:FUME_HOOD":["A capela foi registrada na página em que a oficina trocou a posição do exaustor. A fuligem na face interna mostrava até onde o ar tinha circulado antes da mudança.","O desenho da corrente de ar repete uma curva do caderno do vento.",["wind_staff","A curva do vento"],["npc_carbon","A folha da capela"]],
    "block:REED":["O junco da margem dobra na linha que a água alcança antes da cheia. Os remadores cortavam os talos mais altos para lembrar a última posição em que o bote ainda passava.","Um desses talos ficou prensado na planta de um cais.",["dinghy","A altura que o bote guardou"]],
    lumen_moth:["A mariposa-lúmen passa entre manchas de húmus violeta. Quando se afasta do chão, a luz das asas aparece sobre o fundo por um instante a mais que o corpo.","O brilho que fica parado pertence ao cogumelo ao pé da trilha.",["block:GLOW_FUNGUS","O brilho rente ao chão"],["cristalume","Uma luz que também se move"]],
    "block:AIR":["O levantamento do templo incluiu a distância entre a porta e a parede que ainda estava de pé. Os construtores contaram o espaço vazio em blocos, como se ele tivesse peso.","O mesmo intervalo aparece no desenho de uma câmara submersa.",["block:SUNKEN_MOSAIC","O intervalo sob a água"]],
    "block:GRASS":["Os primeiros mapas da planície registram quais faixas de grama voltavam a crescer depois da passagem dos rebanhos. Seus caminhos ainda aparecem quando se olha de uma encosta alta.","No fim de uma faixa pisada costuma haver uma sombra larga.",["bison","A sombra larga da pradaria"]],
    "block:DIRT":["O caderno de cultivo guardou uma mancha de terra de cada canteiro. A tinta desbotou primeiro na folha que veio sem nenhum vestígio de raiz.","Na contracapa ainda há três grãos presos a uma dobra.",["block:FARMLAND","A marca da primeira enxada"]],
    "block:STONE":["Nas obras antigas, a pedra de uma mesma encosta tem faces diferentes conforme a maneira como foi partida. A patrulha encontrou um degrau tão gasto que só o lado enterrado preservava o corte.","O próximo degrau tinha a mesma orientação e outra idade.",["block:FIELDSTONE","O corte do outro degrau"]],
    "block:SAND":["Na costa, os grãos leves apagam os desenhos deixados durante a noite. Debaixo da primeira camada, linhas mais pesadas guardam a posição do mar no inverno anterior.","Perto de velhos caminhos, a areia costuma cobrir em vez de preencher.",["dune_sentinel","Quem ficou sob a duna"]],
    "block:BEDROCK":["As sondagens mais antigas acabam onde as ferramentas deixaram de avançar. Na amostra desenhada à margem, cada camada escura corta a anterior em um ângulo novo.","A última anotação da mina diz apenas que a batida voltou pelo cabo.",["earth_dragon","A batida que voltou"]],
    "block:DEEPSTONE":["A pedra profunda guarda um veio mais escuro que o resto da galeria. Sob uma luz baixa, as linhas do veio aparecem inteiras entre duas cavidades onde a água trabalhou.","Uma das cavidades coincide com o corte desaparecido da broca.",["drill","A espiral que termina aqui"],["block:BEDROCK","Sob a última galeria"]],
    "block:MAGMA_ROCK":["A rocha conserva brasa em fissuras estreitas, mesmo com a superfície opaca. Em encostas vulcânicas, pedaços separados pelo resfriamento ainda formam um desenho contínuo se vistos de cima.","A parte mais viva do desenho aponta para a sombra de uma asa.",["fire_dragon","A sombra sobre as fissuras"],["block:LAVA","A faixa que ainda corre"]],
    "block:LAVA":["Nos mapas de campo, a lava deixa uma linha que muda depois que o resto da pedra parece assentado. A linha mais recente entra na garganta do vale e desaparece perto de uma dobra escura.","Alguns cortes no basalto descem até essa dobra.",["block:BASALT","O corte da margem"],["block:MAGMA_ROCK","As fendas que guardam calor"]],
    "block:WATER":["A primeira trilha azul do laboratório foi desenhada depois de uma cheia. Os riscos mais fundos no papel correspondem às margens onde o nível voltava ao mesmo ponto.","Um desses riscos reaparece pelo lado interno de um baú.",["boat","O risco na madeira"],["block:LAB_GUIDE_BLUE","A trilha azul"]],
    "block:COAL":["O carvão do primeiro forno deixou marcas que se quebram no meio de dois anéis escuros. Quem o recolheu anotou que as galerias secas guardavam o pó por mais tempo.","O forno mais antigo ainda tem um sulco sob as cinzas.",["block:FURNACE","O sulco sob as cinzas"]],
    "block:SILVER_ORE":["A equipe separou uma amostra de prata que refletia a lua cheia mesmo misturada à rocha. Na ficha de saída do laboratório, alguém trocou a palavra brilho por risco.","Uma lâmina voltou com terra de curral e um único sulco.",["werewolf","O sulco interrompido"],["silver_sentinel","A outra marca de prata"]],
    "block:IRON":["O ferro foi seguido da mina até o primeiro portão da vila. No chão em volta do veio, os mineiros encontraram pilhas de cascalho acima de túneis que já tinham se fechado.","O veio reaparece como faixas nas costas de um animal.",["iron_armadillo","As faixas do casco"],["block:GATE_IRON","O ferro do portão"]],
    "block:COPPER":["O cobre recolhido às margens das termas passa do escuro ao verde nas partes em que a água permanece. Um fragmento encontrado sob uma bancada conserva uma linha limpa ao redor de um furo.","Na oficina, essa linha tem a largura de uma junta móvel.",["cobrete","A junta que envelheceu"]],
    "block:CRYSTAL":["Os primeiros cristais foram vistos à luz de um bicho que mudava de cor no teto. Depois que ele saiu, um veio inteiro ainda parecia aceso, embora o fundo da gruta tivesse escurecido.","A ficha tem duas setas apontando para a mesma rachadura.",["cristalume","A luz que se move"]],
    "block:ASH":["As cinzas do campo não formam um círculo uniforme. Os guias aprenderam a ler a parte em que o capim sobreviveu para estimar por onde veio o fogo.","Há faixas em zigue-zague onde a cinza nunca se espalha.",["boitata","O zigue-zague preservado"],["headless_mule","As cinzas onde houve cascos"]],
    "block:SALT":["Na salina, o vento empurra os grãos soltos até a borda da crosta. Depois de uma noite fria, as marcas mais antigas ganham um contorno branco e voltam a parecer recentes.","Em algumas poças, o sal se acumula só do lado do rosto.",["salt_medusa","O rosto virado para a poça"]],
    "block:BASALT":["Onde a corrente quente tocou água, o basalto se partiu em superfícies estreitas. De longe, as colunas parecem alinhar a entrada de um lugar que os mapas marcam mais à frente.","Uma coluna tem o mesmo corte de uma antiga sentinela.",["den_sentinel","O corte que se move"]],
    "block:OBSIDIAN":["A obsidiana devolve formas escuras antes de devolver qualquer cor. Os mineiros escolhiam as faces em que cabia a passagem inteira, com margem para o que vinha atrás.","Uma lasca guardou o contorno de uma mão fechada.",["golem","A mão fechada"],["obsidian_medusa","O reflexo duplicado"]],
    "block:BASALT_GLASS":["O vidro basáltico fica no limite entre o que queimou e o que endureceu de uma vez. Nas notas das expedições, costuma ter duas linhas de perfil sobre a mesma amostra.","A segunda linha coincide com o desenho antigo da caldeira.",["obsidian_medusa","Uma linha que olha de volta"]],
    "block:LAB":["A primeira Bancada Química foi nivelada sobre um mosaico incompleto. O registro de montagem traz medições nas duas primeiras colunas. A terceira contém apenas a posição em que a água deixou uma marca.","Carbono deixou a página seguinte fora da numeração.",["npc_carbon","A página sem número"]],
    "block:FURNACE":["O forno de pedra mais antigo foi levantado com sobras escuras de três viagens. As juntas do lado da chaminé levaram mais tempo para secar, mas só a soleira guardou o padrão de tijolo.","A marca no último tijolo coincide com uma construção mais ao norte.",["block:VILLAGE_BRICK","A outra soleira"]],
    "block:VILLAGE_BRICK":["Tijolos da primeira vila trazem uma marca de molde diferente nos lados que ficavam para fora. Alguns lotes reaparecem em soleiras antigas no caminho de outra povoação.","O mesmo sinal aparece chamuscado do lado que dá para a estrada.",["headless_mule","A soleira da estrada"],["bucket","Como o tijolo reapareceu"]],
    "block:BRONZE_BLOCK":["Um lote de bronze foi usado para reforçar o batente da praça. As duas partes do batente envelheceram em ritmos diferentes. A anotação do ferreiro tem a mesma data em duas páginas.","As manchas nos encaixes lembram a sombra de duas asas.",["time_dragon","A sombra em dias diferentes"]],
    "block:BED":["A armação das primeiras camas foi feita no tamanho das tábuas trazidas pela estrada. O pano da cabeceira guarda lã de um rebanho que costumava descer antes do temporal.","Na manhã seguinte, as mesmas marcas levam de volta ao quarto.",["sheep","O fio preso"],["block:PLANK","O veio da armação"]],
    "block:PLANK":["Tábuas da mesma árvore conservam parte do desenho do veio, mesmo depois de passar pela serra. Os carpinteiros alinhavam as peças dos batentes antes de cortar o resto para móveis.","Uma sequência termina na altura da cabeceira.",["block:BED","A tábua da cabeceira"],["block:WOOD","Antes da serra"]],
    "block:WOOD":["As primeiras colunas do laboratório eram de madeira de margem. Cortadas pelo mesmo carpinteiro, ainda têm riscos de medida no lado que olha para a água.","As colunas finas ficam a duas marcas de machado da mesma raiz.",["curupira","Duas marcas no toco"]],
    "block:GLASS":["O vidro do laboratório mais antigo nasceu de areia clara e guarda bolhas finas junto às quinas. Quem abre a janela de manhã consegue distinguir o lote pelo reflexo sobre a bancada.","Num desses reflexos apareceram pegadas em cima do beiral.",["cat","A sombra sobre a janela"],["shield_mirror","O outro tipo de reflexo"]],
    "block:TORCH":["Uma tocha bem seca repete a inclinação do vento antes de ele varrer a cinza pelo caminho. O primeiro registro de uma chama inclinada para o lado contrário também fala de um assobio.","Neste ponto do mapa só há uma pegada.",["saci","Onde ficou uma pegada"],["block:FIRE","A mesma cinza no chão"]],
    "block:FIRE":["A chama de uma fogueira baixa deixa um círculo largo de calor e um anel fino de carvão. Em certos campos, o lado de fora desse anel permanece frio mesmo depois de horas.","Dois observadores anotaram que a chama se curvou antes de apagar.",["boitata","A curva luminosa"],["saci","A outra fogueira"]],
    "block:GATE_WOOD":["No primeiro curral, a marca do portão foi talhada no lado para o qual as vacas costumavam virar. Quando a dobradiça passou ao outro lado, a marca ficou na peça antiga.","Os bezerros continuaram tomando a passagem velha.",["cow","O caminho dos bezerros"]],
    "block:GATE_BAMBOO":["A vila usou juntas leves para a abertura do caminho que mais pegava vento. Em uma temporada de tempestades, o bambu avisava pela vibração antes de as aves correrem para a cobertura.","A mesma cobertura guarda penas em todas as estações.",["chicken","Debaixo da cobertura"]],
    "block:GATE_IRON":["Uma dobradiça do portão foi achada por baixo de um lote de tijolos. Era pesada demais para a armação que a cobria. O ferreiro marcou um terceiro encaixe antes de reaproveitá-la.","Na parte enterrada havia um resto de terra de outra cor.",["bucket","O lote que trouxe a dobradiça"],["block:IRON","De onde veio o ferro"]],
    "block:SUNKEN_MOSAIC":["Peças do mosaico continuam assentadas debaixo da água. Cada desenho se repete depois de uma faixa vazia. O padrão termina exatamente onde o canto de uma baleia costuma ecoar no registro do cais.","O desenho do baú termina na última faixa intacta.",["ship","O entalhe de bordo"],["humpback","A última nota na bacia"]],
    "block:SUNKEN_BEACON":["A construção submersa se alinha à parte mais escura da bacia. De cima é possível ver o ponto onde a luz se divide, ainda que o fundo inteiro tenha sumido.","A última anotação de bordo marca um som vindo do mesmo lugar.",["humpback","O canto ouvido sobre a ruína"],["block:SUNKEN_MOSAIC","O desenho do fundo"]],
    "block:EXPEDITION_CHEST":["As caixas de expedição trazem ferragens de todo o vale. Quase todas têm a marca de uma ferramenta por dentro, em vez da marca do dono. Algumas reapareceram fechadas em lugares que o mapa deixou vazios.","Num dos encaixes, o machado tinha a largura da lâmina desenhada por Íris.",["npc_ranger","A largura da ferramenta"],["block:EXPEDITION_CHEST_OPEN","O vestígio que sobrou"]],
    "block:EXPEDITION_CHEST_OPEN":["A tampa aberta guardou um desenho que o pó do fundo já tinha perdido. A forma coincide com a caixa fechada do inventário e com a parte que faltava de um mapa do vale.","Só uma parte do fecho permanece fora de vista.",["block:EXPEDITION_CHEST","A forma no inventário"]],
  });

  const cropNotes={
    strawberry:["O morango amadurece junto ao chão, fora da sombra da folha maior. As primeiras mudas do vale apareceram numa beirada que todo ano recebia o degelo.","Na primavera, os estolões atravessam a divisa antes do fruto."],
    dragon_fruit:["As primeiras flores da pitaieira foram vistas depois da última ronda da noite. O fruto maduro ficou no lado oposto à sombra do tutor.","Riscos de um tutor mais velho reaparecem nas estacas da cerca."],
    blackberry:["Amoras manchavam de roxo os dedos dos guias da floresta. Era assim que quem ficava na vila sabia qual caminho os outros tinham tomado.","É possível seguir as bagas que caíram até a copa mais baixa."],
    jabuticaba:["A jabuticabeira fica cheia de pequenos pontos claros no tronco antes de escurecer com os frutos. As manchas mais baixas mudam toda vez que passam animais pela margem.","Uma jabuticaba intacta ficou presa acima da marca que o rio deixou.",["opossum","Quem subiu pela raiz"],["nature_dragon","O pólen junto às escamas"]],
    acerola:["As acerolas de três lobos ficaram famosas entre os que cruzavam o trecho seco da savana. Há um caderno cujos riscos de dedo ficaram na cor exata da casca madura.","As flores dos ramos de cima aparecem antes de o caminho secar."],
    lime:["Limoeiros de encosta cresceram junto das paredes que recebiam sol depois do meio-dia. Em um desses pomares, os cortes da enxertia ainda guardam a posição dos ramos mais antigos.","Uma casca seca foi parar no armário de reagentes.",["npc_carbon","A amostra que voltou seca"]],
    pomegranate:["O cálice da romã deixa uma pequena coroa no lado do fruto voltado para baixo. Os oleiros das chapadas usaram essa forma para identificar o lote da estação.","A mesma coroa aparece marcada na face interna de alguns tijolos.",["block:VILLAGE_BRICK","A marca na argila"]],
    grapes:["Quando as uvas amadurecem, os cachos mais velhos pesam para o lado em que o tutor já se inclina. Na vila, a orientação desse suporte revela de onde vinha o vento na época da primeira colheita.","Alguns tutores de videira e de pitaya têm o mesmo tipo de nó.",["dragon_fruit","O nó na outra estaca"]],
    starfruit:["As cinco pontas da carambola aparecem no papel manchado de sumo de um desenho de campo. Uma das figuras foi repetida mais tarde no caderno das águas, escrita de lado.","Quem desenhou a segunda estrela tinha visto a primeira inteira.",["block:LAB_GUIDE_BLUE","A estrela no caderno"]],
    wheat:["Os primeiros feixes de trigo da vila foram amarrados na direção em que soprava o vento. O ano da cheia deixou só uma fileira madura no terreno mais alto.","As espigas colhidas por último apontavam para a saída da água."],
    carrot:["Na horta mais velha, as raízes cresceram tortas onde havia um degrau enterrado. A fileira só voltou ao rumo nas últimas três plantas.","O outro lado do degrau estava cheio de sulcos de porco.",["pig","Os sulcos do outro lado"]],
    bean:["O feijoeiro conseguiu alcançar o alto da horta dobrando a cerca mais fina. Anos depois o poste ainda conservava as marcas das primeiras vagens.","As sementes foram contadas no lado da cerca que pega menos chuva.",["block:FENCE_BAMBOO","O lado mais seco"]],
    beet:["As folhas vermelhas da beterraba aparecem antes que a raiz colore a terra ao redor. Os hortelãos datam a primeira safra por uma lasca de madeira que ficou rosada.","Nas bordas da mesma horta vivem os que procuram as raízes caídas.",["pig","Quem procura sob as folhas"]],
    potato:["Os tubérculos crescem reunidos em pequenos bolsões abaixo das folhas. Antes da primeira geada, a horta de altitude guardava mais batatas sob a terra do que mostrava plantas de cima.","Na margem do diário, um forno foi desenhado ainda apagado.",["block:KITCHEN_STOVE","O forno à margem do diário"]]
  };
  Object.assign(notes,cropNotes);
  const fishNotes={
    fish:["Desenha voltas pequenas em água doce e quase sempre passa rente à margem antes de seguir a corrente. O primeiro registro repete a trajetória em três pontos do mesmo rio.","A curva mais funda aparece na ficha da carpa.",["raw_carp","A curva mais funda"]],
    carp:["A carpa encontra bolsões calmos em braços de rio que a espuma parece contornar. Quando o cardume vira, os flancos dourados ficam visíveis pela lateral do barco.","O brilho antigo ocorre antes do junco que dobra sem vento.",["block:REED","O junco perto da curva"]],
    perch:["A perca costuma parar entre o leito de pedras e a corrente. A primeira faixa de sua lateral reaparece quando o sol chega à água de lado.","Uma listra parecida vai em outro sentido na truta.",["raw_trout","A listra da água mais fria"]],
    mullets:["Tainhas passam em grupos nas entradas de água salgada. O primeiro movimento do grupo levanta uma faixa curta de espuma até a borda da maré.","As pegadas nessa margem só aparecem quando o grupo já passou.",["fishfolk_head","O que o cardume deixa ver"]],
    trout:["A truta atravessa água clara contra a corrente num trajeto que pode ser repetido ao pé da cachoeira. Quando para, a faixa do corpo se alinha com a sombra das pedras.","A ponta do registro tem um pequeno desenho de gelo.",["raw_char","O segundo desenho no frio"]],
    catfish:["O bagre examina o fundo antes de sair de sob as raízes. Seus barbilhões tocam a lama primeiro, deixando um risco fino que se repete mais adiante.","Quando o fundo fica macio demais, o risco muda de lado.",["raw_eel","O rastro no lodo mole"]],
    char:["O salvelino conserva manchas claras no dorso mesmo onde a água está escura. A patrulha de inverno seguiu um grupo até abaixo da linha do gelo.","Ali, o veio azul se confunde com as manchas mais próximas umas das outras.",["block:BLUE_ICE_VEIN","O azul sob a borda"]],
    shrimp:["O camarão fica entre as pedras em que a maré deposita conchas. Na ponta de uma corrente estreita, vários exemplares reviram o mesmo pequeno monte sem se espalhar.","O cascalho do outro lado da maré tem um visitante maior.",["salt_crab","Do outro lado da maré"]],
    eel:["O corpo comprido da enguia cabe no espaço entre duas raízes que parecem se tocar. Na água escura, só o primeiro movimento denuncia de que lado ela vai emergir.","O mesmo lugar conserva um rastro de fundo deixado por barbilhões.",["raw_catfish","O rastro interrompido"]],
    pacu:["Os pacus passam onde caem sementes da mata tropical. Em águas calmas, dá para seguir o cardume pelo intervalo entre as pequenas ondulações, muito depois de o último fruto afundar.","O clarão no fim do trajeto pode pertencer a outro cardume.",["piranha","O clarão no outro cardume"]],
    emberfish:["O peixe de brasa foi desenhado no ponto em que a água muda de cor perto da caldeira. Pequenas manchas se juntam no dorso conforme ele se aproxima da corrente quente.","As aves abandonam primeiro as pedras que ainda escurecem no banho.",["block:MAGMA_ROCK","A pedra da corrente quente"]]
  };
  for(const [id,record] of Object.entries(fishNotes))notes["raw_"+id]=record;

  const materials=[
    [/FENCE|GATE|WALL$/,"fence","As passagens mais antigas mudaram de lado quando o terreno cedeu. O lado dos encaixes indica onde a primeira estrada cortava o curral.","A última peça ainda guarda a posição da dobradiça.","block:GATE_WOOD","O lado da dobradiça"],
    [/ICE|GLACIAL|FROST|SNOW|HOAR/,"cold","A equipe de inverno recolheu as bordas onde a água parou primeiro. Em cada uma, o lado voltado para a passagem guardava uma camada mais fina.","O veio azul aparece pouco antes de o gelo ceder.","block:BLUE_ICE_VEIN","O azul que aparece primeiro"],
    [/LAVA|MAGMA|VOLCAN|SCORIA|TUFF|PUMICE/,"volcanic","As amostras vieram da encosta que muda de forma depois da passagem da lava. O lado quebradiço apontava para o calor no desenho original.","A cor mais escura reaparece na primeira curva da caldeira.","block:MAGMA_ROCK","A primeira curva da caldeira"],
    [/MOSAIC|GUIDE|CIVIC|PATH/,"paving","Os construtores deixavam um intervalo entre cada par de figuras inteiras. No inventário mais antigo, esse intervalo foi medido pelo ponto em que a água parava.","Há outro desenho com a mesma distância entre os traços.","block:SUNKEN_MOSAIC","O intervalo no fundo da bacia"],
    [/GLASS|WINDOW|PANE/,"glass","A primeira face recebeu o nome da cor que só aparecia depois de esfriar. A umidade do lado de fora guardou a forma da peça no próprio caixilho.","No vidro ao lado o reflexo começa um pouco acima.","block:GLASS","O reflexo do beiral"],
    [/ROOF|THATCH|AWNING/,"roof","A cobertura foi registrada no dia em que o vento voltou à vila. O lado que secou por último indica em que direção a chuva cruzou a rua.","Riscos mais finos reaparecem na janela de baixo.","block:WINDOW_LEADED","Os riscos da janela"],
    [/PLASTER|BRICK|MASONRY/,"masonry","Quem levantou as paredes marcava os lotes pelo sinal mais claro. Na obra mais antiga, a marca de assentamento ficou do lado que olhava a estrada.","A mesma marca aparece chamuscada perto de uma viela.","block:VILLAGE_BRICK","A soleira da estrada"],
    [/LEAVES|LEAF|FLOWERED/,"canopy","A mudança de cor foi vista primeiro na parte baixa da copa. Subiu lentamente para o lado em que as aves já se reuniam ao anoitecer.","Na casca, um risco foi feito justamente no dia da mudança.","living_tree_elder","A data gravada na copa"],
    [/LOG|WOOD|_END|PLANK/,"wood","O corte preservou a curva dos veios que os carpinteiros distinguiam na árvore de pé. Nos trechos mais altos, o mesmo corte guardava a marca de outra estação.","Onde a raiz fez uma volta, outros veios ainda crescem juntos.","living_tree","Onde os veios crescem juntos"],
    [/_BLOCK$|INGOT/,"alloy","A fundição deixou uma borda de teste onde o molde esfriou primeiro. No registro da oficina, a posição dessa marca indica a ordem em que as peças saíram.","Um molde antigo guarda o mesmo risco mais perto da emenda.","block:METAL_FORGE","A ordem no molde"],
    [/DEEP|CAVERN|GEODE/,"deep","A anotação de sondagem separa duas posições na galeria. Em uma delas, a face da amostra sugere uma passagem anterior ao corte que hoje dá acesso.","Uma luz mais baixa revela o contorno que faltava.","block:DEEPSTONE","O contorno na galeria"],
    [/SHORE|SALT|SAND|RIVER|WATER|SUNKEN/,"shore","A coleta aconteceu numa faixa que a água alcança até o mesmo ponto. A parte coberta por mais tempo conservou outra cor quando a patrulha voltou com a maré baixa.","No mapa de bordo, uma linha fina acompanha a parte mais clara.","boat","A linha do outro mapa"],
    [/DIRT|SOIL|LOAM|PEAT|MUD|FARMLAND|PODZOL|LOESS/,"soil","A chuva arrastou folhas para a dobra do terreno onde a amostra foi recolhida. A camada mais fina acompanha o lugar em que a primeira raiz mudou de direção.","No canteiro da vila, o mesmo sedimento aponta para a primeira fileira.","block:FARMLAND","O sedimento no canteiro"]
  ];
  const station=["A montagem segue uma marca de oficina conservada na Vila dos Elementos. O lado mais gasto indica onde o material ficava antes de cada ensaio.","Uma marca antiga reaparece na bancada que recebeu o lote seguinte.","block:LAB","A bancada do lote seguinte"];
  const ore=["Os prospectores registraram a face exposta e a face recém-partida em páginas diferentes. Um risco de carvão ficou no lado que seria examinado primeiro.","O mesmo risco indica os lotes que chegaram à bancada.","block:ASSAY_BENCH","O risco de carvão"];
  const botany=["A primeira observação foi registrada pelo contorno da planta contra a trilha. No desenho mais antigo, a borda recebe menos luz que o meio da folha.","Uma flor prensada ficou entre as folhas de um mapa.","npc_ranger","A página que guardou a flor"];
  const stone=["O levantamento distingue a face antiga do bloco do lado marcado quando o caminho abriu. A superfície teve tempo de gastar antes que o corte seguinte fosse feito.","A parte sem desgaste ainda lembra um degrau da vila.","block:STONE","A face conservada"];
  function fromBlock(entry){
    const type=entry.blockType,key=entry.key;
    const family=materials.find(([pattern])=>pattern.test(key));
    let report=type==="station"?station:type==="mineral"&&!/GEODE|ICE|FROST/.test(key)?ore:
      entry.plant&&!/LOG|LEAVES|LEAF|_END/.test(key)?botany:family?family.slice(2):stone;
    if(type==="building"&&report===stone)report=[
      "A peça aparece no inventário da primeira obra que abriu para a estrada. Durou o suficiente para herdar marcas de reparo de duas oficinas.",
      "A parte escondida conserva a posição do primeiro encaixe.","block:EXPEDITION_CHEST","A marca no encaixe"];
    const [observation,clue,related,label]=report;
    const {texture,shade}=entry.loreData??{};
    const faces=Array.isArray(texture)&&new Set(texture).size>1;
    const rgb=typeof shade==="string"&&/^#[0-9a-f]{6}$/i.test(shade)?parseInt(shade.slice(1),16):null;
    const gray=rgb===null?null:[rgb>>16,rgb>>8&255,rgb&255];
    let stamp=" entrou no levantamento do vale. ";
    if(faces)stamp=" tem um desenho por face no caderno mais antigo. ";
    else if(gray&&Math.max(...gray)<110)stamp=" deixou o primeiro contorno escuro no inventário. ";
    else if(gray&&gray.every(v=>v>170))stamp=" aparece no papel com as bordas sombreadas a carvão. ";
    else if(gray&&gray[0]-gray[2]>62)stamp=" foi comparado às amostras ocres da primeira coleta. ";
    else if(gray&&gray[2]-gray[0]>45)stamp=" ficou entre as amostras de tom frio no levantamento. ";
    return [entry.name+stamp+observation,clue,[related,label]];
  }
  const fieldRoutes={
    "selva tropical":["jaguar","O rastro na margem da selva"],manguezal:["caiman","A rampa na água baixa"],
    pântano:["peat_slime","A película no brejo"],taiga:["wolf","O rastro de neve"],savana:["lion","O chamado acima do campo"],
    montanha:["earth_dragon","O eco na encosta"],salinas:["salt_medusa","A forma que o sal guardou"],
    tundra:["rime_fox","A marca na geada"],"fiordes glaciais":["orca","O canal aberto"],
    "chapadas ocres":["block:OCHRE_STONE","Uma sombra na chapada"],"delta salobro":["fishfolk_head","As pegadas na água rasa"],
    "bosque lilás":["living_tree_cherry","O caminho das pétalas"],vulcânico:["magma","Um clarão no chão"],
    floresta:["curupira","A trilha que fez a volta"],"floresta de sequoias":["block:REDWOOD_LOG","As marcas na casca"],
    "campina de aurora":["aurora_phantom","A luz na campina"],"prado alpino":["snow_hare","A pequena trilha na geada"],
    "termas minerais":["block:TRAVERTINE","Onde a água deixou marcas"],planície:["bison","O caminho mais largo"]
  };
  const cropPhase={
    wild:"O exemplar silvestre veio de uma abertura na vegetação. A posição das folhas ficou marcada na página que antecede o primeiro registro da horta.",
    sprout:"O broto foi anotado antes de as folhas mostrarem sua forma definitiva. O desenho seguinte foi feito alguns dias depois, do lado oposto do canteiro.",
    growing:"Nesta fase, os hortelãos mediram a distância das folhas até o ponto em que o peso começava a inclinar os ramos. A página seguinte guardava a medida final.",
    ripe:"A planta madura foi desenhada junto da última folha intacta. A mancha no papel indica onde a colheita foi colocada antes de seguir para a vila."
  };
  function fromCrop(entry){
    const {food,seed,phase}=entry.loreData;
    const base=cropNotes[food];
    const story=phase?entry.name+". "+cropPhase[phase]:
      entry.key===seed?entry.name+" foi separado na mesa de cultivo em uma manhã de vento baixo. O rótulo mais antigo indica a posição da primeira fileira que vingou.":
      base?.[0]??entry.name+" vingou na parte da horta em que a água encontrou a terra mais funda. O primeiro registro conserva a posição das folhas no fim da tarde.";
    return [story,base?.[1]??"No mapa da horta, a altura da última chuva ainda aparece.",
      [entry.key===food?seed:food,entry.key===food?"A primeira fileira":"A página da colheita"],...(base?.slice(2)??[]),["block:SEED_BENCH","O registro da horta"]];
  }
  const equipmentLinks=[
    [/spectral|ghost|phantom/,"O contorno da peça apareceu sobre a madeira antes que a oficina acendesse a luz.",["block:SPECTRAL","O contorno na madeira"]],
    [/silver/,"O primeiro polimento deixou terra fina presa junto à borda. O registro seguinte foi escrito no dia da lua cheia.",["werewolf","O risco de lua cheia"]],
    [/ice|frost|glacial|snow/,"A amostra ficou fria muito depois que a geada deixou o cabo. No registro, a linha de orvalho bifurca no ponto em que a peça foi recolhida.",["ice_dragon","A linha que se divide"]],
    [/fire|magma|ember/,"A oficina registrou um risco escuro perto da parte que permanecia fria. A ronda seguinte seguiu o mesmo risco até a caldeira.",["fire_dragon","O rastro de brasa"]],
    [/venom|petrif|acid/,"A peça voltou com uma camada opaca na ponta. No segundo ensaio, a mancha seguiu a direção que os viajantes já conheciam pelas rochas.",["pit_viper","A marca que ficou na ponta"]],
    [/wind|air/,"No primeiro ensaio, o apontador marcou o vento e a altura da parede. As duas direções só coincidem no desenho visto de lado.",["glider","A prancha vista de lado"]],
    [/nature|wood|leaf|archer/,"O desenho conserva uma folha perto da emenda. Os artesãos deixaram o mesmo lado da madeira voltado para fora.",["nature_dragon","A folha junto ao ninho"]],
    [/.*/,"A primeira peça guarda um risco antigo sob a emenda. Foi medido na mesma bancada que recebeu o lote seguinte.",["block:METAL_FORGE","A marca antiga da oficina"]]
  ];
  const weapons={
    bow:"No caderno dos arqueiros, o primeiro risco marca onde a corda descansa. O segundo fica perto da flecha encontrada depois da ronda.",
    crossbow:"No primeiro desenho, a guia repete a medida do virote mais antigo. A ranhura interior guarda a primeira correção feita em campo.",
    staff:"A oficina marcou a posição do foco numa folha que já trazia o desenho da mão. As marcas de uso começam um pouco abaixo do encaixe.",
    sword:"O armeiro guardou o desenho junto do fragmento que voltou da trilha. A dobra no papel ainda coincide com a ponta afiada.",
    mace:"A forja contou as provas pelas marcas redondas na superfície de ensaio. As duas últimas batidas foram dadas no mesmo lugar.",
    gauntlet:"A primeira medida foi tirada com os dedos entreabertos. Quando o molde voltou, havia pó nos pontos cobertos pela mão."
  };
  const apprentices={
    pigment:["Separou os primeiros pigmentos pela marca que cada pó deixava num pano molhado. Uma mancha no caderno ficou da cor do frasco mesmo depois que o papel secou.","A tira mais escura ficou ao lado da primeira mistura."],
    crystal:["Começou alinhando amostras de cristal pela hora em que cada face recebia luz. O primeiro registro traz um desenho com uma aresta repetida em todas as pedras.","A primeira e a última aresta pertencem ao mesmo lote."],
    alloy:["Aprendeu a separar moldes pelo momento em que deixavam de estalar. No caderno, o primeiro metal ganhou uma marca que acompanhava a junta mais fria.","O molde mais antigo guarda o mesmo sinal virado para dentro."],
    water:["Levou para a oficina dois frascos retirados da mesma margem em horas diferentes. Antes da primeira anotação, já havia duas linhas distintas marcadas no vidro.","A medida maior coincide com a água do degrau mais baixo."],
    thermal:["Seu primeiro ensaio deixou duas faixas no vidro, feitas em lados opostos do aquecedor. Guardou a marca da condensação entre os desenhos que usaria no dia seguinte.","Uma segunda peça ficou morna do outro lado do balcão."]
  };
  function fromEquipment(entry){
    const [,clue,link]=equipmentLinks.find(([pattern])=>pattern.test(entry.key+" "+(entry.loreData?.element??"")));
    const category=entry.category;
    const text=category==="shield"?"O escudo voltou com marcas concentradas acima da alça. O lado de dentro guarda um golpe mais antigo, registrado sob outra data.":
      category==="gear"?"A costura mais funda fica na emenda que os viajantes apertavam antes de sair. A oficina manteve o ponto quando refez o primeiro modelo.":
      category==="focus"?"O foco aparece nos diagramas sempre no lado oposto à área de maior intensidade. Os dois primeiros ensaios conservaram a mesma distância entre os pontos.":
      weapons[entry.loreData?.family]??"O primeiro ensaio foi anotado ao lado de um desenho em perfil. Os cortes mais antigos ficaram na parte que o desenho mostra inteira.";
    return [entry.name+" consta no caderno de oficina. "+text,clue,link];
  }
  function fromResident(entry){
    const {region,school,title,role}=entry.loreData??{};
    if(school){
      const teacher=entry.key.startsWith("alchemy:");
      const [trial,trace]=apprentices[school]??["Fez os primeiros ensaios perto da janela. O caderno guarda as datas em que as amostras foram deixadas para secar.","A outra mão escreveu junto à janela."];
      return [teacher?entry.name+" montou sua oficina quando os materiais começaram a chegar de caminhos diferentes. Marca o canto de cada folha com o lote que saiu primeiro.":
        trial,teacher?"Em duas páginas soltas, mãos diferentes escreveram a mesma medida.":trace,
        [teacher?"apprentice:"+school:"alchemy:"+school,"A outra mão na oficina"],["npc_carbon","A folha de aferição"]];
    }
    const station=/(armor|geolog|mineral)/.test(role)?["block:ASSAY_BENCH","As amostras trazidas na primeira viagem"]:
      /(cook|food)/.test(role)?["block:KITCHEN_STOVE","A primeira fornada"]:
      /(hydro|liquid)/.test(role)?["block:LAB_GUIDE_BLUE","O mapa das águas"]:
      /(botan|farm|ecolog)/.test(role)?["block:SEED_BENCH","As primeiras fileiras"]:["block:CIVIC_MARKER","O sinal no centro da praça"];
    const place=region?" em "+region:" na Vila dos Elementos";
    return [entry.name+" passou a marcar as entregas"+place+" em folhas soltas. "+(title?
      "As primeiras páginas trazem o ofício de "+title.toLocaleLowerCase("pt-BR")+" junto à data de chegada.":
      "Há duas folhas com a mesma assinatura, feitas em horários diferentes."),
      "O caminho do primeiro carregamento reaparece desenhado por outra mão.",station,["npc_ranger","O mapa de Íris"]];
  }
  function fromCreature(entry){
    const {key,name,category}=entry,{regions,habitat,source}=entry.loreData??{};
    const where=regions?.[0],link=fieldRoutes[where];
    const place=where?" em "+where:habitat&&habitat!=="Pescado"?" em "+habitat.toLocaleLowerCase("pt-BR"):" nas voltas mais antigas do levantamento";
    if(key.startsWith("living_tree"))return [name+" acompanha a direção em que a copa encontra espaço. Os veios da casca conservam curvas de raízes que cresceram longe de onde o tronco repousa.",
      "Entre duas voltas da casca ficou a marca de uma mão pequena.",["living_tree_warden","As raízes que escutam"],["curupira","Outra marca na casca"]];
    if(category==="aquatic")return [name+" foi observado"+place+". A primeira linha no registro acompanha o fundo. A segunda marca onde o animal virou em direção à superfície.",
      "O intervalo entre as linhas muda junto da maré.",["block:WATER","A medida da antiga cheia"],["boat","A marca a bordo"]];
    if(category==="fantasy")return [name+" deixou sinais"+place+". O rastro e o lugar em que a criatura apareceu receberam marcas diferentes no mesmo mapa.",
      "O contorno anterior ainda está na folha usada para comparação.",[key.includes("golem")?"block:ASSAY_BENCH":key.includes("sentinel")?"block:EXPEDITION_CHEST":"npc_ranger","O registro de antes"],...(link?[link]:[])];
    if(source)return [name+" ganhou ficha própria depois que a patrulha encontrou suas pegadas"+place+". As duas formas guardam o mesmo desenho de pata, cercado por sedimentos de cores diferentes.",
      "O contorno anterior ficou guardado na ficha usada como comparação.",[source,"A ficha da outra margem"],...(link?[link]:[])];
    return [name+" aparece no caderno das trilhas"+place+". A patrulha marcou o ponto onde o animal parou e o rastro que saiu dali.",
      "Há um pequeno corte na página onde o caminho muda.",...(link?[link]:[]),["npc_ranger","O caminho no mapa"]];
  }
  function describe(entry,lookup=new Map()){
    const {key,name,category}=entry;
    let record=entry.loreData?.food?fromCrop(entry):Object.hasOwn(notes,key)?notes[key]:null;
    if(!record&&key.endsWith(":ghost")){
      const base=key.slice(0,-6),animal=lookup.get(base)?.name||name.split(" · ")[0];
      const track=category==="aquatic"?"A ondulação fica para trás, embora a água adiante já mostre o contorno.":
        "A forma conserva o mesmo gesto e reaparece alguns passos além da primeira sombra.";
      record=["O relato de "+animal+" ganhou outra folha quando a equipe voltou ao mesmo lugar depois do anoitecer. "+track,
        "O primeiro registro guarda o ponto comum aos dois avistamentos.",[base,"A ficha do primeiro avistamento"],
        [base==="werewolf"?"block:SILVER_ORE":"block:SPECTRAL","O traço que permaneceu"]];
    }
    if(!record&&key.endsWith(":baby")){
      const base=key.slice(0,-5),animal=lookup.get(base)?.name||name.split(" · ").at(-1);
      record=["Os filhotes de "+animal+" seguem os adultos até o ponto em que as pegadas se separam. A primeira trilha solitária costuma acabar perto do mesmo abrigo.",
        "O caminho mais comprido pertence à ficha do adulto.",[base,"Onde a trilha se divide"]];
    }
    if(!record&&category==="block")record=fromBlock(entry);
    if(!record&&["weapon","shield","gear","focus"].includes(category))record=fromEquipment(entry);
    if(!record&&category==="npc")record=fromResident(entry);
    if(!record)record=fromCreature(entry);
    const [story,clue,...references]=record;
    const links=references.filter(([id],i)=>id!==key&&lookup.has(id)&&references.findIndex(([other])=>other===id)===i)
      .slice(0,2).map(([key,label])=>({key,label}));
    return {story,clue,links};
  }
  return {describe};
})();
